// ─── CONFETTI ────────────────────────────────────────────────────────────────
function ConfettiCannon({ color, onDone }) {
  const canvasRef = useRef(null);
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight;
    const pieces = Array.from({ length: 90 }, () => ({
      x: Math.random() * canvas.width,
      y: -20 - Math.random() * 60,
      r: 4 + Math.random() * 6,
      dx: (Math.random() - 0.5) * 3,
      dy: 2.5 + Math.random() * 3.5,
      angle: Math.random() * Math.PI * 2,
      spin: (Math.random() - 0.5) * 0.18,
      opacity: 1,
      shape: Math.random() > 0.5 ? "rect" : "circle",
      w: 8 + Math.random() * 8,
      h: 5 + Math.random() * 5,
    }));
    let frame;
    let elapsed = 0;
    const DURATION = 2800;
    const tick = () => {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      elapsed += 16;
      const progress = Math.min(elapsed / DURATION, 1);
      pieces.forEach(p => {
        p.x += p.dx;
        p.y += p.dy;
        p.angle += p.spin;
        p.dy += 0.06;
        p.opacity = Math.max(0, 1 - Math.pow(progress, 2.5));
        ctx.save();
        ctx.globalAlpha = p.opacity;
        ctx.fillStyle = color;
        ctx.translate(p.x, p.y);
        ctx.rotate(p.angle);
        if (p.shape === "rect") {
          ctx.fillRect(-p.w / 2, -p.h / 2, p.w, p.h);
        } else {
          ctx.beginPath();
          ctx.arc(0, 0, p.r, 0, Math.PI * 2);
          ctx.fill();
        }
        ctx.restore();
      });
      if (progress < 1) {
        frame = requestAnimationFrame(tick);
      } else {
        if (onDone) onDone();
      }
    };
    frame = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frame);
  }, [color, onDone]);
  return (
    <canvas
      ref={canvasRef}
      style={{
        position: "fixed", top: 0, left: 0,
        width: "100vw", height: "100vh",
        pointerEvents: "none", zIndex: 99999,
      }}
    />
  );
}

function ShatterEffect({ x = 0, y = 0, onDone }) {
  const canvasRef = useRef(null);
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight;
    const shards = Array.from({ length: 26 }, () => {
      const angle = Math.random() * Math.PI * 2;
      const speed = 3 + Math.random() * 6;
      return {
        x, y,
        dx: Math.cos(angle) * speed,
        dy: Math.sin(angle) * speed - 2,
        rot: Math.random() * Math.PI * 2,
        spin: (Math.random() - 0.5) * 0.3,
        w: 6 + Math.random() * 14,
        h: 6 + Math.random() * 14,
        opacity: 1,
      };
    });
    let frame;
    let elapsed = 0;
    const DURATION = 700;
    const tick = () => {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      elapsed += 16;
      const progress = Math.min(elapsed / DURATION, 1);
      shards.forEach(p => {
        p.x += p.dx;
        p.y += p.dy;
        p.dy += 0.32;
        p.rot += p.spin;
        p.opacity = Math.max(0, 1 - Math.pow(progress, 1.8));
        ctx.save();
        ctx.globalAlpha = p.opacity;
        ctx.fillStyle = "#dc2626";
        ctx.strokeStyle = "#7f1d1d";
        ctx.lineWidth = 1;
        ctx.translate(p.x, p.y);
        ctx.rotate(p.rot);
        ctx.fillRect(-p.w / 2, -p.h / 2, p.w, p.h);
        ctx.strokeRect(-p.w / 2, -p.h / 2, p.w, p.h);
        ctx.restore();
      });
      if (progress < 1) {
        frame = requestAnimationFrame(tick);
      } else {
        if (onDone) onDone();
      }
    };
    frame = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frame);
  }, [x, y, onDone]);
  return (
    <canvas
      ref={canvasRef}
      style={{
        position: "fixed", top: 0, left: 0,
        width: "100vw", height: "100vh",
        pointerEvents: "none", zIndex: 99999,
      }}
    />
  );
}

// ─── ENGINE ──────────────────────────────────────────────────────────────────
function computeInnings(dels = []) {
  let runs = 0, wickets = 0, legal = 0;
  const bat = {}, bowl = {};

  for (const d of dels) {
    const isRetiredOutType = d.wicketType === "No Reason" || d.wicketType === "Retired Out";
    if (d?.retired || isRetiredOutType) {
      const retiredName = canonicalPlayerName(d.retiredPlayer || d.dismissed || d.striker || "");
      const retirementType = d.retirementType || (isRetiredOutType ? "out" : "hurt");
      if (retiredName) {
        if (!bat[retiredName]) bat[retiredName] = { runs: 0, balls: 0, fours: 0, sixes: 0, out: false, dismissal: "" };
        bat[retiredName].dismissal = retirementType === "out" ? "retired out" : "retired hurt";
        if (retirementType === "out") bat[retiredName].out = true;
      }
      continue;
    }

    const dead = !!d.deadBall;
    const W = !!d.wide;
    const NB = !!d.noBall;
    const L = !W && !NB && !dead;
    const r = d.runs || 0;

    runs += r + (W ? 1 : 0) + (NB ? 1 : 0);
    if (L) legal++;

    const countsOnNoBall = d.wicketType === "Run Out";
    const out = !!d.wicket && (!NB || countsOnNoBall) && !dead;
    if (out) wickets++;

    const strikerName = canonicalPlayerName(d.striker || "");
    if (!W && strikerName) {
      if (!bat[strikerName]) bat[strikerName] = { runs: 0, balls: 0, fours: 0, sixes: 0, out: false, dismissal: "" };
      bat[strikerName].runs += r;
      if (L) bat[strikerName].balls++;
      if (r === 4) bat[strikerName].fours++;
      if (r === 6) bat[strikerName].sixes++;
    }

    const dismissedName = canonicalPlayerName(d.dismissed || "");
    if (out && dismissedName) {
      if (!bat[dismissedName]) bat[dismissedName] = { runs: 0, balls: 0, fours: 0, sixes: 0, out: false, dismissal: "" };
      bat[dismissedName].out = true;
      bat[dismissedName].dismissal = d.dismissalText || d.wicketType || "out";
    }

    const bowlerName = canonicalPlayerName(d.bowler || "");
    if (bowlerName) {
      if (!bowl[bowlerName]) bowl[bowlerName] = { runs: 0, balls: 0, wickets: 0 };
      bowl[bowlerName].runs += r + (W ? 1 : 0) + (NB ? 1 : 0);
      if (L) bowl[bowlerName].balls++;
      if (out && d.wicketType !== "Run Out" && !isRetiredOutType && !dead) bowl[bowlerName].wickets++;
    }
  }

  const overs = Math.floor(legal / 6), balls = legal % 6;
  const ovH = [];
  let cur = [], lg = 0;

  for (const d of dels) {
    cur.push(d);
    if (d?.retired) continue;
    if (isLegalDelivery(d)) {
      lg++;
      if (lg >= 6) {
        ovH.push(cur);
        cur = [];
        lg = 0;
      }
    }
  }

  if (cur.length) ovH.push(cur);
  return { runs, wickets, overs, balls, legal, batters: bat, bowlers: bowl, overHistory: ovH };
}

function matchDesc(r1,r2,r2wkts,bt1,bt2,standalone){
  if(r2>r1){
    const wicketsRemaining = 4 - r2wkts;
    return `${bt2} won by ${wicketsRemaining} ${wicketsRemaining===1?"wicket":"wickets"}`;
  }

  if(r1>r2){
    const d=r1-r2;
    return `${bt1} won by ${d} ${d===1?"run":"runs"}`;
  }

  return "Match tied";
}

function aggregateAllStats(matchStates){
  const S={};
  const g=n=>{if(!S[n])S[n]={name:n,team:PLAYER_TEAM[n]||"",bat_mat:0,bat_inn:0,bat_runs:0,bat_balls:0,bat_hs:0,bat_4s:0,bat_6s:0,bat_outs:0,bat_50s:0,bat_ducks:0,bowl_mat:0,bowl_inn:0,bowl_balls:0,bowl_runs:0,bowl_wkts:0,bowl_bbi_r:999,bowl_bbi_w:0,bowl_4w:0,field_catches:0,field_ro:0,field_st:0};return S[n];};
  const seen={};
  for(const [mid,ms] of Object.entries(matchStates)){
    if(!ms?.innings)continue;
    for(const inn of ms.innings){
      if(!inn?.deliveries?.length)continue;
      const c=computeInnings(inn.deliveries);
      for(const [n,b] of Object.entries(c.batters)){const p=g(n);if(!seen[`${mid}b${n}`]){seen[`${mid}b${n}`]=1;p.bat_mat++;}p.bat_inn++;p.bat_runs+=b.runs;p.bat_balls+=b.balls;p.bat_4s+=b.fours;p.bat_6s+=b.sixes;if(b.out)p.bat_outs++;if(b.runs>p.bat_hs)p.bat_hs=b.runs;if(b.runs>=50)p.bat_50s++;if(b.runs===0&&b.out)p.bat_ducks++;}
      for(const [n,b] of Object.entries(c.bowlers)){const p=g(n);if(!seen[`${mid}w${n}`]){seen[`${mid}w${n}`]=1;p.bowl_mat++;}p.bowl_inn++;p.bowl_balls+=b.balls;p.bowl_runs+=b.runs;p.bowl_wkts+=b.wickets;if(b.wickets>p.bowl_bbi_w||(b.wickets===p.bowl_bbi_w&&b.runs<p.bowl_bbi_r)){p.bowl_bbi_w=b.wickets;p.bowl_bbi_r=b.runs;}if(b.wickets>=4)p.bowl_4w++;}
      for(const d of inn.deliveries){if(!d.wicket||!d.fielder)continue;const p=g(d.fielder);if(d.wicketType==="Caught")p.field_catches++;else if(d.wicketType==="Run Out")p.field_ro++;else if(d.wicketType==="Stumped")p.field_st++;}
    }
  }
  return Object.values(S);
}


function computePoints(matchStates){
  const T={};
  for(const c of Object.keys(TEAMS))T[c]={team:c,p:0,w:0,l:0,pts:0,rf:0,bf:0,ra:0,ba:0};
  for(const fx of FIXTURES){
    if(!["league","demo"].includes(fx.stage))continue;
    const ms=matchStates[fx.id];
    if(!ms||ms.status!=="completed"||!ms.result)continue;
    const{winner,t1,t2,t1Runs:r1,t2Runs:r2,t1Balls:b1,t2Balls:b2}=ms.result;
    if(!T[t1]||!T[t2])continue;
    T[t1].p++;T[t2].p++;
    T[t1].rf+=Number(r1)||0;T[t1].bf+=Number(b1)||60;T[t1].ra+=Number(r2)||0;T[t1].ba+=Number(b2)||60;
    T[t2].rf+=Number(r2)||0;T[t2].bf+=Number(b2)||60;T[t2].ra+=Number(r1)||0;T[t2].ba+=Number(b1)||60;

    const pts = ms.result.points || {};
    T[t1].pts+=Number(pts[t1] ?? 0);
    T[t2].pts+=Number(pts[t2] ?? 0);

    if(winner==="tie"){}
    else if(winner===t1){T[t1].w++;T[t2].l++;}
    else if(winner===t2){T[t2].w++;T[t1].l++;}
  }
  return Object.values(T).map(t=>({
    ...t,
    nrr:t.bf>0&&t.ba>0 ? +((t.rf/t.bf*6)-(t.ra/t.ba*6)).toFixed(3) : 0
  })).sort((a,b)=>b.pts-a.pts||b.nrr-a.nrr);
}

function applyStandingsOverrides(rows, standingsAdjustments = {}) {
  if (!Array.isArray(rows)) return [];
  return rows.map((row) => {
    const adj = standingsAdjustments?.[row.team] || {};
    const next = { ...row };

    if (Object.prototype.hasOwnProperty.call(adj, "nrr")) {
      const delta = Number(adj.nrr);
      if (Number.isFinite(delta)) {
        next.nrr = +((Number(row.nrr) || 0) + delta).toFixed(3);
      }
    }

    if (Object.prototype.hasOwnProperty.call(adj, "pts")) {
      const delta = Number(adj.pts);
      if (Number.isFinite(delta)) {
        next.pts = +(Number(row.pts || 0) + delta).toFixed(2);
      }
    }

    return next;
  }).sort((a, b) => b.pts - a.pts || b.nrr - a.nrr);
}


function buildCommentary(deliveries){
  const overs=[];let cur=[],lg=0;
  for(const d of deliveries){
    cur.push(d);
    if(d?.retired) continue;
    if(isLegalDelivery(d)){lg++;if(lg>=6){overs.push([...cur]);cur=[];lg=0;}}
  }
  if(cur.length)overs.push(cur);
  return overs.map((ov,oi)=>{
    const runs=ov.reduce((s,d)=>s+(d.runs||0),0);
    const extras=ov.filter(d=>d.wide||d.noBall).length;
    const wkts=ov.filter(d=>d.wicket).length;
    const balls=ov.map((d)=>{
      const r=d.runs||0;let desc="";
      if(d.retired)desc=`↩ RETIRED ${d.retirementType==="out"?"OUT":"HURT"} — ${d.retiredPlayer||d.striker||"Batter"}`;
      else if(d.deadBall && d.wicket)desc=`💀 Dead-ball wicket! ${d.dismissed||"Batter"} — ${d.dismissalText||d.wicketType||"dismissed"}`;
      else if(d.deadBall)desc="💀 Dead ball — no play";
      else if(d.wicket)desc=`❌ OUT! ${d.dismissed||"Batter"} — ${d.dismissalText||d.wicketType||"dismissed"}`;
      else if(d.noBall)desc=`⚡ NO BALL — ${r>0?`${r} run${r>1?"s":""} scored. `:""}FREE HIT next`;
      else if(d.wide)desc=`📏 Wide${r>0?` +${r}`:""} — extra awarded`;
      else if(r===6)desc=`🟣 SIX! ${d.striker||"Batter"} off ${d.bowler||"bowler"}`;
      else if(r===4)desc=`🟢 FOUR! ${d.striker||"Batter"} off ${d.bowler||"bowler"}`;
      else if(r===0)desc=`• Dot — ${d.bowler||"bowler"} to ${d.striker||"batter"}`;
      else desc=`${r} run${r>1?"s":""} — ${d.striker||"Batter"} off ${d.bowler||"bowler"}`;
      return{...d,desc};
    });
    return{over:oi+1,runs,wkts,extras,balls,summary:wkts?`${runs} runs, ${wkts}W`:`${runs} runs`};
  });
}

function getRetiredStatus(deliveries = []) {
  const retired = {};
  for (const d of deliveries) {
    if (d?.retired && d.retiredPlayer) {
      retired[d.retiredPlayer] = d.retirementType || "hurt";
      continue;
    }
    if (d?.wicketType === "Retired Out" || d?.wicketType === "No Reason") {
      const retiredName = d.dismissed || d.striker || "";
      if (retiredName) retired[retiredName] = "out";
    }
  }
  return retired;
}

function normalizeLiveBatting(live = {}, options = {}) {
  const next = { ...live };
  const { promoteSolo = true } = options;

  if (promoteSolo && !next.striker && next.nonStriker) {
    next.striker = next.nonStriker;
    next.nonStriker = "";
  }

  const solo = !!next.striker && !next.nonStriker;
  next.standaloneMode = solo;
  next.standalonePlayer = solo ? next.striker : "";
  return next;
}

const isLegalDelivery = (d = {}) => !d?.wide && !d?.noBall && !d?.deadBall && !d?.retired && d?.wicketType !== "Retired Out";

const todayStr=()=>{const d=new Date();return`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`;};
const hasRealObjectKeys = (value) => !!(value && typeof value === "object" && Object.keys(value).length > 0);
const canEdit = (fx, qualifiedTeamsOverride = null) => {
  if (!fx) return false;
  if (fx.stage === "demo" || fx.date === todayStr()) return true;
  if (fx.stage === "semi" || fx.stage === "final") {
    return hasRealObjectKeys(qualifiedTeamsOverride);
  }
  return false;
};
