function deliveryMiniLabel(del){
  const runs = Number(del?.runs || 0);
  if (del?.retired) return del?.retirementType === "out" ? "RO" : "RH";
  if (del?.deadBall && del?.wicket) return "D+W";
  if (del?.deadBall) return "D";
  if (del?.wicket) return del?.wide ? (runs > 0 ? `${runs}+W` : "WdW") : (runs > 0 ? `${runs}W` : "W");
  if (del?.noBall) return runs > 0 ? `${runs}+NB` : "NB";
  if (del?.wide) return runs > 0 ? `${runs}+Wd` : "Wd";
  if (runs === 0) return "·";
  return String(runs);
}

function getCurrentOverDeliveries(deliveries = []) {
  const current = [];
  let legal = 0;

  for (const d of deliveries || []) {
    if (d?.retired) continue;
    current.push(d);
    if (isLegalDelivery(d)) {
      legal += 1;
      if (legal >= 6) {
        current.length = 0;
        legal = 0;
      }
    }
  }

  return current;
}

function getBowlingTypeOverCounts(deliveries = []) {
  let paceOvers = 0;
  let spinOvers = 0;
  let legal = 0;
  let currentOverType = "";

  for (const d of deliveries || []) {
    if (d?.retired) continue;
    if (!currentOverType && d?.ballType) {
      currentOverType = d.ballType;
    }

    if (isLegalDelivery(d)) {
      legal += 1;
      if (legal >= 6) {
        if (currentOverType === "pace") paceOvers += 1;
        if (currentOverType === "spin") spinOvers += 1;
        legal = 0;
        currentOverType = "";
      }
    }
  }

  return { paceOvers, spinOvers };
}

