  Math.floor((inn.bowlers?.[name]?.balls || 0) / 6);

const MAX_BOWLER_OVERS = 5;

const canBowl = (name) => {
  if (isUnavailablePlayer(name)) return false;
  const overs = bowlerOvers(name);
  return overs < MAX_BOWLER_OVERS;
};

