  const all=useMemo(()=>aggregateAllStats(matchStates),[matchStates]);

  const adjustedAll=useMemo(
    ()=>all.map((p)=>applyManualStatOverrides(p, statsAdjustments)),
    [all,statsAdjustments]
  );

  const rows=useMemo(()=>{
    if(tab==="bat") return [...adjustedAll].filter(p=>p.bat_inn>0).sort((a,b)=>b.bat_runs-a.bat_runs);
    if(tab==="bowl") return [...adjustedAll].filter(p=>p.bowl_inn>0).sort((a,b)=>b.bowl_wkts-a.bowl_wkts);
    return [...adjustedAll].filter(p=>p.field_catches+p.field_ro+p.field_st>0).sort((a,b)=>(b.field_catches+b.field_ro+b.field_st)-(a.field_catches+a.field_ro+a.field_st));
  },[adjustedAll,tab]);

  const rawPlayer = useMemo(() => {
    if (!editName) return null;
    return all.find(p => p.name === editName) || null;
  }, [all, editName]);

