    today:{label:"Today",color:"#fbbf24",bg:"rgba(251,191,36,.1)"},
    past:{label:"Missed",color:"rgba(255,255,255,.3)",bg:"rgba(255,255,255,.04)"},
    upcoming:{label:"Upcoming",color:"rgba(255,255,255,.22)",bg:"rgba(0,0,0,.03)"},
